#' Bifactor CFA
#'
#' Orthogonal bifactor model: every item loads on a general factor and on one 
#' specific factor. Reports omega hierarchical, explained common variance 
#' (ECV), Item ECV, and visual diagnostics (antenna plot and facing combs).
#' 
#'
#' @examples
#' \donttest{
#' data('wizlab', package = 'psyWiz')
#' psyWiz::bifactorCfa(wizlab, run = TRUE, generalName = 'Wellbeing', factors = list(
#'     list(label = 'Body', vars = paste0('body', 1:4)),
#'     list(label = 'Mind', vars = paste0('mind', 1:4)),
#'     list(label = 'Social', vars = paste0('social', 1:4))))
#'}
#' @param data the data as a data frame
#' @param factors a list of lists, each with a \code{label} (the factor name)
#'   and \code{vars} (the names of its items)
#' @param generalName a string, the name of the general factor
#' @param run \code{TRUE} or \code{FALSE} (default), fit the models; while
#'   \code{FALSE} only a summary of the plan is shown
#' @param type \code{'auto'} (default; ordinal variables are treated as
#'   ordinal, continuous ones as continuous), \code{'ordinal'} or
#'   \code{'continuous'}
#' @param estimator \code{'auto'} (default; MLR for continuous items, WLSMV
#'   for ordinal items), \code{'ML'}, \code{'MLR'}, \code{'MLM'},
#'   \code{'WLSMV'}, \code{'ULSMV'}, \code{'DWLS'} or \code{'ULS'}
#' @param missing \code{'auto'} (default; FIML for ML and MLR, pairwise
#'   deletion for ordinal items), \code{'listwise'}, \code{'fiml'} or
#'   \code{'pairwise'}
#' @param showIndices \code{TRUE} (default) or \code{FALSE}, show omega, omega
#'   hierarchical and ECV
#' @param showLoadings \code{TRUE} (default) or \code{FALSE}, show the
#'   standardized loadings
#' @param highlight \code{TRUE} or \code{FALSE} (default), highlight poor fit
#'   indices, high uniqueness (> 0.80), and items weak (< 0.30) on both factors
#'   in red
#' @param showAntenna \code{TRUE} (default) or \code{FALSE}, draw the antenna
#'   plot: general factor to the left, specific to the right
#' @param showFacing \code{TRUE} or \code{FALSE} (default), draw the general
#'   and the specific combs growing towards each other, with the unique variance
#'   of each item in between
#' @param showPath \code{TRUE} or \code{FALSE} (default), draw the path
#'   diagram
#' @param pathNumbers \code{TRUE} (default) or \code{FALSE}, print the
#'   standardized loadings on the arrows
#' @param pathWidth \code{TRUE} (default) or \code{FALSE}, make the width of
#'   an arrow proportional to its loading
#' @param plotFit \code{'none'} (default), \code{'below'} or \code{'above'},
#'   print the model fit measures and estimator on the figure
#' @param showPlotGuide \code{TRUE} (default) or \code{FALSE}, show a short
#'   reading guide above each novel plot
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$fit} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$indices} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$loadings} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$antennaDesc} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$antenna} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$facingDesc} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$facing} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$pathFig} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$fit$asDF}
#'
#' \code{as.data.frame(results$fit)}
#'
#' @export
bifactorCfa <- function(
    data,
    factors = list(
                list(label="Factor 1", vars=list()),
                list(label="Factor 2", vars=list())),
    generalName = "General",
    run = FALSE,
    type = "auto",
    estimator = "auto",
    missing = "auto",
    showIndices = TRUE,
    showLoadings = TRUE,
    highlight = FALSE,
    showAntenna = TRUE,
    showFacing = FALSE,
    showPath = FALSE,
    pathNumbers = TRUE,
    pathWidth = TRUE,
    plotFit = "none",
    showPlotGuide = TRUE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("bifactorCfa requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- bifactorCfaOptions$new(
        factors = factors,
        generalName = generalName,
        run = run,
        type = type,
        estimator = estimator,
        missing = missing,
        showIndices = showIndices,
        showLoadings = showLoadings,
        highlight = highlight,
        showAntenna = showAntenna,
        showFacing = showFacing,
        showPath = showPath,
        pathNumbers = pathNumbers,
        pathWidth = pathWidth,
        plotFit = plotFit,
        showPlotGuide = showPlotGuide)

    analysis <- bifactorCfaClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

